async function api(path,data){const r=await fetch(path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Portal-Token':window.PORTAL_TOKEN},body:JSON.stringify(data)});let d;try{d=await r.json()}catch{throw Error('서버 응답을 읽을 수 없습니다. Crawler Hub 실행 상태를 확인하세요.')}if(!r.ok)throw Error(d.error||'요청에 실패했습니다.');return d}
