async function navigate(page){if(S.page==='mapping'&&page!=='mapping')await saveMappingDrafts();if(!titles[page])page='new';S.page=page;Object.keys(titles).forEach(k=>hide('page-'+k,k!==page));$('pageTitle').textContent=titles[page];document.querySelectorAll('#navigation button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));history.replaceState(null,'','#'+page);if(page==='history')await loadHistory();if(page==='new'){await refreshBrands();renderWizard();}if(page==='admin')await loadAdmin();if(page==='mapping')await loadMapping();if(page==='monitor'){await openMonitorPage();}if(page==='review'){await loadJobChoices('review');S.reviewKey='';await loadReview(true)} }
