function selectBrand(id){S.brand=id;S.validation=null;renderBrands();renderGuide();renderSummary();renderFields()}
function renderBrands(){const query=$('brandSearch').value.toLowerCase(),recent=S.settings.recent_brands||[];let rows=[...S.brands].sort((a,b)=>{const ai=recent.indexOf(a.id),bi=recent.indexOf(b.id);return (ai<0?99:ai)-(bi<0?99:bi)});$('brandCards').replaceChildren();if(!S.brands.length){empty($('brandCards'),'등록된 브랜드가 없습니다','관리자에서 새 브랜드를 추가하세요.');$('brandCards').append(button('브랜드 등록하기',()=>navigate('admin'),'primary'));}for(const b of rows.filter(b=>brandLabel(b).toLowerCase().includes(query))){let n=button('',()=>selectBrand(b.id),'brand-card'+(b.id===S.brand?' selected':''));n.disabled=!b.available;if(b.image_mode==='local')n.append(el('span','이미지 저장','image-save-badge'));if(b.mapping_mode==='manual')n.append(el('span','색상 매핑 필요','mapping-required-badge'));n.append(el('b',brandLabel(b)),el('small',b.category+(b.available?'':' · 파일 없음')));if(recent.includes(b.id))n.append(el('span','최근 사용','recent-label'));$('brandCards').append(n)}}
