function inputData(){if(!brand())throw Error('관리자에서 브랜드를 먼저 등록하세요.');if(S.inputMode==='excel'&&!S.file)throw Error('엑셀 파일을 먼저 선택해주세요.');return {brand:S.brand,codes:$('codes').value,file:S.inputMode==='excel'?S.file:null,demo:false,selected:S.selected,name:$('jobName').value}}
