function inputChanged(){S.validation=null;const codes=$('codes').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);$('inputCount').textContent=codes.length+'개 품번 · 중복 '+(codes.length-new Set(codes).size)+'개';$('validationResult').replaceChildren();renderSummary()}
