function renderWizard(){renderInputMode(false);for(let i=1;i<=3;i++)hide('step'+i,S.step!==i);$('stepper').replaceChildren();['브랜드 선택','품번 입력 및 검증','수집 항목 및 실행'].forEach((title,i)=>{const d=el('div',undefined,i+1===S.step?'current':i+1<S.step?'complete':'');d.append(el('b',i+1<S.step?'✓':String(i+1)),el('span',title));$('stepper').append(d)});$('prevStep').disabled=S.step===1;$('nextStep').textContent=S.step===3?'크롤링 시작 →':'다음 단계 →';$('nextStep').disabled=!brand()?.available;$('stepHint').textContent=S.step+' / 3 단계';renderBrands();renderGuide();renderFields();renderSummary()}
function renderFields(){const b=brand();if(!b){$('requiredFields').replaceChildren();$('optionalFields').replaceChildren();$('columnPreview').replaceChildren();return}for(const [keys,id,required] of [[S.required,'requiredFields',true],[S.optional,'optionalFields',false]]){$(id).replaceChildren();for(const key of keys){const cap=b.fields[key],label=el('label',undefined,'field-option'+(!cap.supported?' unsupported':'')),c=el('input');c.type='checkbox';c.checked=required||S.selected.includes(key)&&cap.supported;c.disabled=required||!cap.supported;c.onchange=()=>{S.selected=c.checked?[...new Set([...S.selected,key])]:S.selected.filter(x=>x!==key);S.validation=null;renderSummary();renderColumns();persistSelection()};const text=el('span',S.fields[key]+(required?' · 필수':''));text.append(el('small',!cap.supported?'수집 불가 · '+(cap.reason||'독립 결과 컬럼 없음'):'결과 컬럼 지원 · 상품별 누락 가능'));label.append(c,text);$(id).append(label)}}renderColumns()}
