async function nextStep(){if(S.step===1){S.step=2;renderWizard();return}if(S.step===2){const v=await validate();if(!v.valid)return toast('입력 오류와 필수 열을 확인해주세요.',true);S.step=3;renderWizard();return}if(active())throw Error('현재 실행 중인 작업을 먼저 완료하거나 중지해주세요.');const v=await validate();if(!v.valid)throw Error('입력 데이터를 다시 확인해주세요.');$('nextStep').disabled=true;try{const d=await api('/api/jobs',inputData());S.settings=await api('/api/settings');resetNewForm();await openJob(d.id,'monitor');toast('크롤링 작업을 시작했습니다.')}finally{$('nextStep').disabled=false}}
async function openJob(id,page='review'){S.jobId=id;localStorage.setItem('crawlerJob',id);S.reviewId=null;S.item=null;$('reviewSearch').value='';$('reviewFilter').value='';S.reviewOffset=S.queueOffset=S.logOffset=0;S.queueKey=S.reviewKey='';S.job=await api('/api/jobs/'+id);if(page==='monitor')S.monitorRequestedId=id;renderHeader();await navigate(page)}
function renderHeader(){const local=S.job?.image_mode==='local'&&S.job?.mapping_finalized;hide('reviewMainImageFolder',!local);hide('reviewAdditionalImageFolder',!local);hide('reviewDetailImageFolder',!local||!S.job?.detail_image_ready);hide('reviewImagesZip',!local);$('reviewImagesZip').href='/api/jobs/'+S.jobId+'/images-zip';for(const id of ['reviewMapping','monitorMapping']){hide(id,S.job?.mapping_mode!=='manual');$(id).disabled=active();$(id).textContent=S.job?.mapping_finalized?'✓ 매핑 완료 · 수정':'색상 매핑하기';} $('headerBrand').textContent=S.job?.brand||'';$('headerState').replaceWith(Object.assign(status(S.job?.state||'WAITING'),{id:'headerState'}))}
