async function poll(){if(S.page==='monitor'&&!S.monitorManual){await refreshCurrentMonitor();}if(S.busy||!S.jobId)return;S.busy=true;try{S.job=await api('/api/jobs/'+S.jobId);S.pollError=false;renderHeader();if(S.page==='monitor'){renderMonitor();await loadQueue();await loadLogs()}if(S.page==='review')await loadReview()}catch(e){if(!S.pollError)toast('로컬 서버 연결을 확인 중입니다. 연결되면 자동으로 갱신합니다.',true);S.pollError=true}finally{S.busy=false}}
function debounce(fn){let timer;return()=>{clearTimeout(timer);timer=setTimeout(run(fn),250)}}
function bind(){
$('brandSearch').oninput=renderBrands;$('codes').oninput=inputChanged;$('insertExample').onclick=() => brand()&&addExample(brand().guide.example);$('directTab').onclick=()=>{S.inputMode='direct';renderInputMode()};$('uploadTab').onclick=()=>{S.inputMode='excel';renderInputMode()};$('file').onchange=run(async()=>{const f=$('file').files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('10MB 이하의 엑셀을 선택하세요.');S.file=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});$('fileName').textContent=f.name;S.validation=null;await validate()});$('validate').onclick=run(validate);$('prevStep').onclick=()=>{S.step=Math.max(1,S.step-1);renderWizard()};$('nextStep').onclick=run(nextStep);$('resetSelection').onclick=()=>{S.selected=['main_image','additional_images','detail_page'];renderFields();renderSummary();persistSelection()};$('pause').onclick=run(()=>jobAction(['paused','pausing'].includes(S.job.state)?'resume':'pause'));$('stop').onclick=run(()=>jobAction('stop'));$('save').onclick=run(()=>jobAction('save'));$('openFolder').onclick=run(()=>jobAction('open-folder'));$('queueSearch').oninput=debounce(()=>{S.queueOffset=0;return loadQueue(true)});$('queueFilter').onchange=run(()=>{S.queueOffset=0;return loadQueue(true)});$('reviewSearch').oninput=debounce(()=>{S.reviewOffset=0;S.reviewId=null;S.item=null;return loadReview(true)});$('reviewFilter').onchange=run(()=>{S.reviewOffset=0;S.reviewId=null;S.item=null;return loadReview(true)});$('historySearch').oninput=renderHistory;$('refreshHistory').onclick=run(loadHistory);$('logPanel').ontoggle=run(loadLogs);$('logSearch').oninput=debounce(()=>{S.logOffset=0;return loadLogs()});$('logFilter').onchange=run(()=>{S.logOffset=0;return loadLogs()});for(const [id,tab] of [['imagesTab','images'],['detailTab','detail'],['rawTab','raw']])$(id).onclick=run(()=>{S.reviewTab=tab;return renderResult()});async function move(delta){const idx=S.reviewRows.findIndex(x=>x.id===S.reviewId),next=S.reviewRows[idx+delta];if(next)await selectResult(next.id);else if(delta>0&&S.reviewOffset+S.reviewRows.length<S.reviewTotal){S.reviewOffset+=50;S.reviewId=null;S.item=null;await loadReview(true)}else if(delta<0&&S.reviewOffset>0){S.reviewOffset-=50;S.reviewId=null;S.item=null;await loadReview(true);const last=S.reviewRows.at(-1);if(last)await selectResult(last.id)}}$('previousProduct').onclick=run(()=>move(-1));$('nextProduct').onclick=run(()=>move(1));document.addEventListener('keydown',run(async e=>{if(S.page!=='review'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||$('lightbox').open)return;if(e.key==='ArrowLeft')await move(-1);if(e.key==='ArrowRight')await move(1)}));$('reviewMainImageFolder').onclick=run(()=>jobAction('open-main-images'));$('reviewAdditionalImageFolder').onclick=run(()=>jobAction('open-additional-images'));$('reviewDetailImageFolder').onclick=run(()=>jobAction('open-detail-images'));$('reviewExport').onclick=()=>{if(S.jobId)window.location.href='/api/jobs/'+S.jobId+'/export'};$('closeLightbox').onclick=()=>$('lightbox').close();bindV03();bindMapping();
}
(async()=>{navigation();bind();try{const [meta,settings]=await Promise.all([api('/api/brands'),api('/api/settings')]);S.brands=meta.brands;S.fields=meta.fields;S.required=meta.required;S.optional=meta.optional;S.settings=settings;S.selected=[...(settings.selected||[])];S.brand=S.brands.find(b=>(settings.recent_brands||[]).includes(b.id))?.id||S.brands[0]?.id||'';$('sidebarVersion').textContent='v'+meta.version;$('headerVersion').textContent='v'+meta.version;renderWizard();if(S.jobId){try{S.job=await api('/api/jobs/'+S.jobId);renderHeader()}catch{S.jobId=null;localStorage.removeItem('crawlerJob')}}await navigate(location.hash.slice(1)||'new');setInterval(poll,1000)}catch(e){toast(e.message,true);empty($('brandCards'),'연결할 수 없습니다','Crawler Hub가 실행 중인지 확인하세요.')}})();

function persistSelection(){run(async()=>{await api('/api/settings',{selected:S.selected});S.settings.selected=[...S.selected]})()}
window.addEventListener('hashchange',run(()=>{const page=location.hash.slice(1);if(page!==S.page)return navigate(page)}));

function resetNewForm(){S.step=1;S.file=null;S.validation=null;S.inputMode='excel';$('codes').value='';$('file').value='';$('fileName').textContent='';$('jobName').value='';$('validationResult').replaceChildren();inputChanged();renderWizard()}
async function loadJobChoices(kind){
 const jobs=await api('/api/history');S.history=jobs;
 const query=$(kind+'JobSearch').value.trim().toLowerCase(),select=$(kind+'JobSelect'),chosen=S.jobId;
 select.replaceChildren(new Option('작업을 검색해서 선택하세요',''));
 jobs.filter(j=>(j.name+' '+j.brand+' '+date(j.created_at)).toLowerCase().includes(query)).forEach(j=>select.add(new Option((j.name?j.name+' · '+j.brand:j.brand)+' · '+date(j.created_at)+' · '+(stateNames[j.state]||j.state),j.id)));
 if([...select.options].some(o=>o.value===chosen))select.value=chosen;
}
async function openMonitorPage(){
 const requested=S.monitorRequestedId;S.monitorRequestedId=null;
 if(requested){S.jobId=requested;S.job=await api('/api/jobs/'+requested);S.monitorManual=!['running','pausing','paused','stopping','saving'].includes(S.job.state);}
 else{S.monitorManual=false;await refreshCurrentMonitor();}
 await loadJobChoices('monitor');renderHeader();renderMonitor();await loadQueue(true);await loadLogs();
}
async function refreshCurrentMonitor(){
 try{const current=await api('/api/active');
  if(current?.id!==S.jobId){S.queueKey='';S.queueOffset=0;S.queueTask=null;$('monitorContext').replaceChildren();}
  S.jobId=current?.id||null;S.job=current;
  if(current&&[...$('monitorJobSelect').options].some(o=>o.value===current.id))$('monitorJobSelect').value=current.id;
  renderHeader();renderMonitor();
 }catch(e){if(!S.pollError)toast('로컬 서버 연결을 확인 중입니다.',true);S.pollError=true;}
}
